#include <algorithm>

int fibonacci(int n) {
    if (n <= 1) {
        return n;
    }
    return fibonacci(n - 1) + fibonacci(n - 2);
}

int main() {
    int n;
    cout << "Enter a positive integer: ";
    cin >> n;

    if (n <= 1) {
        cout << "The Fibonacci sequence is: " << fibonacci(n) << std::endl;
